from lib import *
S = SS('p8')
steps = [
    step("服务器给 www.example.test 设置不带 Domain 的 cookie(host-only)。保存时 domain='www.example.test'、domain_specified=False。之后请求:www.example.test 带上;sub.www.example.test 也带上了——子域名拿到了父主机的 host-only cookie;api.example.test、example.test、other.test 都没带。按我对 RFC 6265 的理解 host-only cookie 只该发给原主机,所以 http.cookiejar 在子域名这里与它不一致(我没有在本机重新核对标准原文)。", t=tl(S(1)), done=lidx(S(1), '之后请求时带上了'), mark=lidx(S(1), '保存下来的'), kv=KV([['api.example.test', '没带'], ['sub.www.example.test', '带上了(子域名)'], ['example.test', '没带']], ['sub.www.example.test'])),
    step("Domain=example.test(从 www.example.test 设置):保存时 domain='.example.test'、domain_specified=True;www、api、example.test、sub.www 都带上,other.test 与 notexample.test(只是后缀碰巧相似)不带。写成 Domain=.example.test(前导点)效果一样。Domain=other.test 是别人的域名,被拒绝,jar 里一个都没有。", t=tl(S(2)), done=lidx(S(2), '之后请求时带上了:[\'www.example.test/\', \'api.example.test/\', \'example.test/\', \'sub'), mark=lidx(S(2), 'Domain=other.test', '被拒绝', '没带:[\'other.test/\', \'notexample.test/\']'), kv=KV([['Domain=example.test', '子域名与根都带上'], ['notexample.test', '不带(不是子域)'], ['Domain=other.test', '被拒绝']], ['Domain=other.test'])),
    step("Path=/app:保存 path='/app'。带上的有 /app、/app/、/app/x;没带的有 /(比 cookie 路径短)、/application(只是字符串前缀,不在路径边界上)、/App(区分大小写)。", t=tl(S(3)), done=lidx(S(3), '之后请求时带上了'), mark=lidx(S(3), '保存下来的'), b=bars([['带上的路径', 3, '3'], ['没带的路径', 3, '3']], 6, done=[0], mark=[1]), kv=KV([['/app、/app/x', '带上'], ['/application', '不带(不在边界上)'], ['/App', '不带(区分大小写)']], ['/application'])),
    step("不写 Path 时用默认路径:cookie 从 /a/b/set 设置,保存的 path='/a/b'(取 URL 路径去掉最后一段)。之后请求 /a/b/x 带上了,/、/a、/a/、/a/c 都没带——在子目录里设置的无 Path cookie,到上一级目录就看不到了。", t=tl(S(4)), done=lidx(S(4), '带上了'), mark=lidx(S(4), '保存的 path'), kv=KV([['从 /a/b/set 设置', 'path 默认 /a/b'], ['/a/b/x', '带上'], ['/a、/a/c、/', '不带']], ['从 /a/b/set 设置'])),
    step("cookie 不区分端口:在端口 A 的服务器上设置的 cookie,发往同主机名、另一个端口的服务器时照样带上。同一个主机名下跑着多个服务(开发机、反向代理后面的多个应用)时,它们会共享 cookie。", t=tl(S(5)), done=lidx(S(5), '之后请求时带上了'), kv=KV([['端口 A 设置', '保存一份'], ['同主机的端口 B', '照样带上'], ['含义', 'cookie 的范围是主机,不含端口']], ['含义'])),
    step("Secure:服务器是 http,Set-Cookie 带 Secure 时 cookie 被保存了(secure=True),但之后对 http 地址的请求不会带上它。过期:先设置 k=v(jar 里 1 个),再收到 Max-Age=0 变成 0 个;收到过去的 Expires(1970 年)也是 0 个——删除 cookie 就是让服务器发一个已过期的同名 cookie。", t=tl(S(6)), done=lidx(S(6), 'Max-Age=0', '过去的 Expires'), mark=lidx(S(6), 'Secure'), kv=KV([['Secure 经 http 收到', '保存了,但不发'], ['Max-Age=0', '删除'], ['过去的 Expires', '删除']], ['Secure 经 http 收到'])),
    step("Domain 设得很宽:Domain=test 与 .test(没有内嵌的点)被拒绝。但 shop.co.uk 设置 Domain=co.uk 或 .co.uk 被接受了,保存为 domain='.co.uk',之后 shop.co.uk、other.co.uk、bank.co.uk 全都带上——一个站点能给同一后缀下的所有站点种 cookie。DefaultCookiePolicy().strict_ns_domain 默认 0(DomainLiberal);改成 DomainStrict(3)后 Domain=co.uk 还是被接受(jar 里 1 个),不写 Domain 的 host-only cookie 照常保存。", t=tl(S(7)), done=lidx(S(7), 'DomainStrict 下不写 Domain'), mark=lidx(S(7), 'Domain=co.uk', 'Domain=.co.uk', 'DomainStrict 后'), b=bars([['shop.co.uk 的 cookie 被带到的站点数', 3, '3'], ['DomainStrict 下 co.uk 仍被接受的个数', 1, '1']], 3, mark=[0, 1]), kv=KV([['Domain=test', '拒绝(无内嵌点)'], ['Domain=co.uk', '接受,发给 other.co.uk'], ['DomainStrict', '仍然接受']], ['Domain=co.uk'])),
    step("手写 headers 与 cookies= 参数的关系:Session 里已有 k=v,请求时再传 cookies={\"extra\":\"1\"},服务器收到 k=v; extra=1(合并发送),但 extra 没有存进 jar(jar 里只有 k)。请求里手写 Cookie 头 manual=2 时,服务器只收到 manual=2——jar 里的 k=v 没有发。不用 Session 的 requests.get 虽然 r.cookies 里有 k,紧接着再 requests.get 同一个主机,服务器收到的 Cookie 是空的。", t=tl(S(8)), done=lidx(S(8), 'extra', 'manual=2'), mark=lidx(S(8), '收到 Cookie: \'\''), kv=KV([['cookies= 参数', '与 jar 合并发送,不入 jar'], ['手写 Cookie 头', '取代 jar 里的 cookie'], ['无 Session 的 get', '不保存,下次不带']], ['手写 Cookie 头'])),
]
A = mkartp('p8', 8, '爬虫,requests,Cookie,CookieJar,Domain,Path,http.cookiejar,公共后缀,Python,真实验证,动画演示',
    '在本机用多个主机名实测 requests 的 Cookie 匹配:没写 Domain 的 cookie 会发给子域名;Domain=example.test 覆盖子域但不覆盖 notexample.test;Path 按目录边界匹配且区分大小写;cookie 不区分端口;Domain=co.uk 被接受并发给 other.co.uk(http.cookiejar 没有公共后缀列表);手写 Cookie 头会取代 jar。',
    'requests.Session 会自动保存和发送 cookie,但“带不带”由 http.cookiejar 决定。这篇用 www.example.test、api.example.test、shop.co.uk 这类名字(只在本进程里解析到本机)逐条测:域、路径、端口、Secure、公共后缀,以及手写 Cookie 头和 cookies= 参数的优先关系。',
    [('sub.www', 'host-only cookie 竟然也发给了子域名 sub.www.example.test'), ('3 个', 'shop.co.uk 设置 Domain=co.uk 后,被带上这个 cookie 的站点数(包括 other.co.uk、bank.co.uk)'), ('/a/b', '从 /a/b/set 设置、没写 Path 的 cookie 的默认路径')],
    [('host-only cookie', '<p>不写 <code>Domain</code> 的 cookie 保存时 <code>domain_specified=False</code>。实测它发给了设置它的 <code>www.example.test</code>,也发给了 <code>sub.www.example.test</code>,没发给 <code>api.example.test</code> 和 <code>example.test</code>。按我对 RFC 6265 的理解,host-only cookie 只该发回原主机——但那只是凭记忆,我没有核对标准文本;可以确定的是 <code>http.cookiejar</code> 会把它发给子域名。</p>'),
     ('Domain 属性', '<p><code>Domain=example.test</code> 让 cookie 对根域和所有子域生效(保存为 <code>.example.test</code>),<code>notexample.test</code> 这种只是字符串后缀相同的不算;<code>Domain=other.test</code> 是别人的域名,被拒绝。</p>'),
     ('Path 属性', '<p><code>Path=/app</code> 匹配 <code>/app</code> 及其下层,不匹配 <code>/</code>、不匹配只是字符串前缀的 <code>/application</code>,也区分大小写。</p>'),
     ('默认路径', '<p>没写 <code>Path</code> 时,cookie 的路径取设置它的 URL 的目录。从 <code>/a/b/set</code> 设置的 cookie 路径是 <code>/a/b</code>,在 <code>/a/c</code> 或 <code>/</code> 就看不到了——爬取时 cookie 突然“丢了”,常常是因为路径。</p>'),
     ('端口不参与', '<p>cookie 的范围是主机名,不含端口。同一个主机名上的两个服务共用 cookie,这在本机开发时尤其容易互相覆盖。</p>'),
     ('Secure 与删除', '<p>经 http 收到的 <code>Secure</code> cookie 会被保存,但对 http 请求不会发送。<code>Max-Age=0</code> 或过去的 <code>Expires</code> 会删掉同名 cookie——这是服务器“清除登录状态”的方式,爬虫的 jar 也会照做。</p>'),
     ('公共后缀', '<p>Python 标准库的 <code>http.cookiejar</code> 没有公共后缀列表。<code>Domain=test</code> 因为没有内嵌的点被拒绝,但 <code>Domain=co.uk</code> 被接受,并发给了 <code>other.co.uk</code>、<code>bank.co.uk</code>;改用 <code>DomainStrict</code> 也没拦住。用同一个 Session 爬很多个同后缀的站点时,一个站点能给其它站点种 cookie。我没有试 <code>blocked_domains</code> 或第三方公共后缀库。</p>'),
     ('三种来源的 cookie', '<p>Session 的 jar、<code>cookies=</code> 参数、手写的 <code>Cookie</code> 头:前两者合并发送,<code>cookies=</code> 里的那份不会存进 jar;手写 <code>Cookie</code> 头则取代 jar,jar 里的不再发送。不用 Session 的 <code>requests.get</code> 不保存 cookie,下一次请求是空的。</p>')],
    steps,
    [ENV_P + '。*.test 与 *.uk 的主机名通过替换本进程的 socket.getaddrinfo 解析到 127.0.0.1(没有改系统 hosts),所以 URL、Host 头、cookie 匹配用的都是这些主机名,服务器记录收到的 Cookie 头;http.cookiejar 为 Python 3.14.8 标准库自带',
     '没有验证:RFC 6265 原文对 host-only、Path 默认值的规定(上文只比较了 http.cookiejar 的行为);HTTPS 站点上 Secure cookie 的发送;SameSite 属性(http.cookiejar 不处理);浏览器的行为;自带公共后缀列表的库(tldextract 等)能否补上这个缺口;cookie 数量与大小上限;aiohttp 的 CookieJar(后面可能单独看)'],
    'Cookie 匹配')
